// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Hop dong thong minh dau tien
contract HelloWorld {
    // Bien trang thai luu tru tren Blockchain
    string public greeting = "Xin chao Web3!";

    // Ham cap nhat loi chao (ghi vao blockchain - ton gas)
    function setGreeting(string memory _greeting) public {
        greeting = _greeting;
    }

    // Ham doc du lieu (view function - khong ton gas)
    function getGreeting() public view returns (string memory) {
        return greeting;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract BankAccount {
    address public owner;
    mapping(address => uint256) public balances;

    constructor() {
        owner = msg.sender; // Nguoi tao hop dong la chu so huu
    }

    // Modifier kiem tra quyen truy cap
    modifier onlyOwner() {
        require(msg.sender == owner, "Chi chu hop dong moi co quyen!");
        _;
    }

    function deposit() public payable {
        balances[msg.sender] += msg.value;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract TransferLogger {
    // Dinh nghia Event voi tu khoa indexed de de dang tim kiem
    event Transfer(address indexed from, address indexed to, uint256 amount);
    event LogMessage(string message);

    function sendToken(address _to, uint256 _amount) public {
        // Phat ra su kien de Frontend lang nghe
        emit Transfer(msg.sender, _to, _amount);
        emit LogMessage("Chuyen tien thanh cong!");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract MyToken is ERC20 {
    // Khoi tao token voi ten goi va ky hieu
    constructor(uint256 initialSupply) ERC20("DevMaster Token", "DMT") {
        // Mint token ban dau cho nguoi tao hop dong
        _mint(msg.sender, initialSupply * 10 ** decimals());
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SecureVault {
    mapping(address => uint256) public balances;
    bool private locked;

    // Khoa chong tan cong tai nhap (Reentrancy Guard)
    modifier noReentrant() {
        require(!locked, "Khong cho phep goi lai!");
        locked = true;
        _;
        locked = false;
    }

    function withdraw() public noReentrant {
        uint256 amount = balances[msg.sender];
        require(amount > 0, "So du khong du");

        // Quy tac CEI: Cap nhat so du TRUOC khi gui tien
        balances[msg.sender] = 0;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Giao dich chuyen tien that bai");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract SimpleStaking {
    IERC20 public stakingToken;
    mapping(address => uint256) public stakedAmount;

    constructor(address _tokenAddress) {
        stakingToken = IERC20(_tokenAddress);
    }

    function stake(uint256 amount) external {
        require(amount > 0, "So luong phai lon hon 0");
        stakingToken.transferFrom(msg.sender, address(this), amount);
        stakedAmount[msg.sender] += amount;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

contract MyVaultV1 is UUPSUpgradeable, OwnableUpgradeable {
    uint256 public totalVaultValue;

    function initialize(address initialOwner) public initializer {
        __Ownable_init(initialOwner);
        __UUPSUpgradeable_init();
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract DaoGovernance {
    struct Proposal {
        uint256 id;
        string description;
        uint256 votesFor;
        uint256 votesAgainst;
        uint256 deadline;
        bool executed;
    }

    mapping(uint256 => Proposal) public proposals;
    uint256 public nextProposalId;

    function createProposal(string calldata desc) external returns (uint256) {
        uint256 id = nextProposalId++;
        proposals[id] = Proposal(id, desc, 0, 0, block.timestamp + 3 days, false);
        return id;
    }
}
